# Now apply to the test input
test_input = [
    [0, 9, 3, 3, 1, 5],
    [7, 5, 3, 3, 1, 7],
    [3, 3, 3, 3, 9, 2],
    [2, 4, 0, 7, 3, 3],
    [4, 3, 5, 3, 3, 3],
    [3, 3, 3, 3, 3, 3]
]

def build_output(input_grid):
    n = len(input_grid)
    output = [[0]* (2*n) for _ in range(2*n)]

    # TL: TL[r][c] = input[r][c]
    for r in range(n):
        for c in range(n):
            output[r][c] = input_grid[r][c]

    # TR: TR[r][c] = input[n-1-c][r]
    for r in range(n):
        for c in range(n):
            output[r][n+c] = input_grid[n-1-c][r]

    # BL: BL[r][c] = input[c][n-1-r]
    for r in range(n):
        for c in range(n):
            output[n+r][c] = input_grid[c][n-1-r]

    # BR: BR[r][c] = input[n-1-r][n-1-c]
    for r in range(n):
        for c in range(n):
            output[n+r][n+c] = input_grid[n-1-r][n-1-c]

    return output

result = build_output(test_input)

print("Output grid (6x6 input -> 12x12 output):")
for row in result:
    print(' '.join(map(str, row)))
